import React, { useState } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  MenuItem,
  Button,
  Grid
} from "@mui/material";

export default function TenderForm() {
  const stateDistrictData = {
    Maharashtra: ["Pune", "Mumbai", "Nagpur", "Nashik"],
    Karnataka: ["Bangalore", "Mysore", "Mangalore"],
    Gujarat: ["Ahmedabad", "Surat", "Vadodara"]
  };

  const [formData, setFormData] = useState({
    companyName: "",
    type: "",
    state: "",
    district: "",
    goodsType: "",
    quantity: "",
    price: ""
  });

  const handleChange = (e) => {
    const { name, value } = e.target;

    setFormData({
      ...formData,
      [name]: value,
      ...(name === "state" && { district: "" }) // reset district when state changes
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log(formData);
    alert("Tender Submitted Successfully");
  };

  return (
    <Box display="flex" justifyContent="center" mt={4}>
      <Card sx={{ width: 600, p: 2 }}>
        <CardContent>
          <Typography variant="h5" align="center" gutterBottom>
            Tender Form
          </Typography>

          <form onSubmit={handleSubmit}>
            <Grid container spacing={2}>
              
              {/* Company Name */}
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Company Name"
                  name="companyName"
                  value={formData.companyName}
                  onChange={handleChange}
                  required
                />
              </Grid>

              {/* Type */}
              <Grid item xs={12}>
                <TextField
                  select
                  fullWidth
                  label="Type"
                  name="type"
                  value={formData.type}
                  onChange={handleChange}
                  required
                >
                  <MenuItem value="">Select Type</MenuItem>
                  <MenuItem value="Broker">Broker</MenuItem>
                  <MenuItem value="Purchaser">Purchaser</MenuItem>
                  <MenuItem value="Wholesaler">Wholesaler</MenuItem>
                </TextField>
              </Grid>

              {/* State */}
              <Grid item xs={12}>
                <TextField
                  select
                  fullWidth
                  label="State"
                  name="state"
                  value={formData.state}
                  onChange={handleChange}
                  required
                >
                  <MenuItem value="">Select State</MenuItem>
                  {Object.keys(stateDistrictData).map((state) => (
                    <MenuItem key={state} value={state}>
                      {state}
                    </MenuItem>
                  ))}
                </TextField>
              </Grid>

              {/* District */}
              <Grid item xs={12}>
                <TextField
                  select
                  fullWidth
                  label="District"
                  name="district"
                  value={formData.district}
                  onChange={handleChange}
                  disabled={!formData.state}
                  required
                >
                  <MenuItem value="">Select District</MenuItem>

                  {formData.state &&
                    stateDistrictData[formData.state].map((dist) => (
                      <MenuItem key={dist} value={dist}>
                        {dist}
                      </MenuItem>
                    ))}
                </TextField>
              </Grid>

              {/* Goods Type */}
              <Grid item xs={12}>
                <TextField
                  select
                  fullWidth
                  label="Goods Type"
                  name="goodsType"
                  value={formData.goodsType}
                  onChange={handleChange}
                  required
                >
                  <MenuItem value="">Select Goods</MenuItem>
                  <MenuItem value="Sugar">Sugar</MenuItem>
                  <MenuItem value="Ethanol">Ethanol</MenuItem>
                  <MenuItem value="Fusel Oil">Fusel Oil</MenuItem>
                  <MenuItem value="Pressmud">Pressmud</MenuItem>
                  <MenuItem value="Ash">Ash</MenuItem>
                </TextField>
              </Grid>

              {/* Quantity */}
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Quantity (in MT)"
                  name="quantity"
                  type="number"
                  value={formData.quantity}
                  onChange={handleChange}
                  required
                />
              </Grid>

              {/* Price */}
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Price per MT"
                  name="price"
                  type="number"
                  value={formData.price}
                  onChange={handleChange}
                  required
                />
              </Grid>

              {/* Submit Button */}
              <Grid item xs={12}>
                <Button
                  fullWidth
                  variant="contained"
                  size="large"
                  type="submit"
                >
                  Submit Tender
                </Button>
              </Grid>
            </Grid>
          </form>
        </CardContent>
      </Card>
    </Box>
  );
}
